25	/** Send an email via Resend API */
26	async function sendViaResend(
27	  apiKey: string,
28	  from: { email: string; name: string },
29	  to: string,
30	  subject: string,
31	  htmlContent: string
32	): Promise<{ ok: boolean; status: number; body: string; errorMessage?: string }> {
33	  const res = await fetch("https://api.resend.com/emails", {
34	    method: "POST",
35	    headers: {
36	      "Authorization": `Bearer ${apiKey}`,
37	      "Content-Type": "application/json",
38	    },
39	    body: JSON.stringify({
40	      from: `${from.name} <${from.email}>`,
41	      to: [to],
42	      subject,
43	      html: htmlContent,
44	    }),
45	  });
46	
47	  const body = await res.text();
48	  let errorMessage: string | undefined;
49	
50	  if (!res.ok) {
51	    try {
52	      const parsed = JSON.parse(body);
53	      errorMessage = parsed.message || parsed.error?.message;
54	    } catch { /* ignore */ }
55	  }
56	
57	  return { ok: res.ok, status: res.status, body, errorMessage };
58	}
