60	serve(async (req) => {
61	  const corsHeaders = {
62	    "Access-Control-Allow-Origin": getCorsOrigin(req),
63	    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
64	  };
65	  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
66	
67	  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
68	  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
69	  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
70	
71	  // Verify JWT
72	  const authHeader = req.headers.get("Authorization");
73	  if (!authHeader) {
74	    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
75	      status: 401,
76	      headers: { ...corsHeaders, "Content-Type": "application/json" },
77	    });
78	  }
79	
80	  const token = authHeader.replace("Bearer ", "");
81	  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
82	  if (authError || !user) {
83	    return new Response(JSON.stringify({ error: "Unauthorized" }), {
84	      status: 401,
85	      headers: { ...corsHeaders, "Content-Type": "application/json" },
86	    });
87	  }
88	
89	  try {
90	    const { resume_id, job_id, to_email, subject, body_html } =
91	      (await req.json()) as SendCandidateEmailRequest;
92	
93	    if (!resume_id || !job_id || !to_email || !subject || !body_html) {
94	      return new Response(
95	        JSON.stringify({ error: "Missing required fields: resume_id, job_id, to_email, subject, body_html" }),
96	        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
97	      );
98	    }
99	
100	    // Load platform config for Resend credentials
101	    const { data: config, error: configError } = await supabase
102	      .from("platform_config")
103	      .select("resend_api_key, email_from_address, email_from_name, outbound_email_enabled")
104	      .limit(1)
105	      .single();
106	
107	    if (configError) throw new Error(`Config error: ${configError.message}`);
108	
109	    if (!config?.outbound_email_enabled) {
110	      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
111	        status: 200,
112	        headers: { ...corsHeaders, "Content-Type": "application/json" },
113	      });
114	    }
115	
116	    if (!config.resend_api_key) {
117	      return new Response(JSON.stringify({ error: "Resend API key not configured" }), {
118	        status: 400,
119	        headers: { ...corsHeaders, "Content-Type": "application/json" },
120	      });
121	    }
122	
123	    const fromEmail = config.email_from_address || "noreply@rankora.co";
124	    const fromName = config.email_from_name || "Rankora";
125	
126	    // Send via Resend
127	    const result = await sendViaResend(
128	      config.resend_api_key,
129	      { email: fromEmail, name: fromName },
130	      to_email,
131	      subject,
132	      body_html
133	    );
134	
135	    const logStatus = result.ok ? "sent" : "failed";
136	
137	    // Log to outreach_log regardless of send result
138	    const { error: logError } = await supabase.from("outreach_log").insert({
139	      resume_id,
140	      job_id,
141	      type: "email",
142	      to_address: to_email,
143	      subject,
144	      status: logStatus,
145	      user_id: user.id,
146	    });
147	
148	    if (logError) {
149	      console.error("Failed to log outreach:", logError.message);
150	      await logSystemError({
151	        function_name: "send-candidate-email",
152	        error_type: "OUTREACH_LOG_ERROR",
153	        severity: "warning",
154	        error_message: `Failed to log outreach: ${logError.message}`,
155	        user_id: user.id,
156	        job_id,
157	      });
158	    }
159	
160	    if (!result.ok) {
161	      const errorMessage = result.errorMessage || `Resend error (status ${result.status})`;
162	
163	      console.error("Resend error:", result.status, result.body);
164	      await logSystemError({
165	        function_name: "send-candidate-email",
166	        error_type: "RESEND_SEND_ERROR",
167	        severity: "warning",
168	        error_message: `Resend error: status=${result.status} body=${result.body}`,
169	        user_id: user.id,
170	        job_id,
171	      });
172	      return new Response(
173	        JSON.stringify({ error: errorMessage }),
174	        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
175	      );
176	    }
177	
178	    return new Response(JSON.stringify({ success: true }), {
179	      status: 200,
180	      headers: { ...corsHeaders, "Content-Type": "application/json" },
181	    });
182	  } catch (err: unknown) {
183	    console.error("send-candidate-email error:", err);
184	    await logSystemError({
185	      function_name: "send-candidate-email",
186	      error_type: "EMAIL_SEND_ERROR",
187	      severity: "warning",
188	      error_message: errorToMessage(err),
189	      error_stack: errorToStack(err),
190	    });
191	    return new Response(
192	      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
193	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
194	    );
195	  }
196	});
