-- SMS logs table for Twilio outreach
create table sms_logs (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  resume_id uuid references resumes(id) on delete set null,
  job_id uuid references jobs(id) on delete set null,
  to_phone text not null,
  message text not null,
  status text not null default 'pending', -- pending|sent|failed
  twilio_sid text,
  error text,
  created_at timestamptz default now()
);

create index idx_sms_logs_user on sms_logs (user_id);
create index idx_sms_logs_resume on sms_logs (resume_id);
create index idx_sms_logs_job on sms_logs (job_id);
create index idx_sms_logs_created_at on sms_logs (created_at desc);

alter table sms_logs enable row level security;

create policy "Users see own sms logs"
  on sms_logs for select
  using (user_id = auth.uid());

create policy "Users insert own sms logs"
  on sms_logs for insert
  with check (user_id = auth.uid());

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const ALLOWED_ORIGINS = [
  Deno.env.get("APP_URL") || "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
];

function getCorsOrigin(req: Request): string {
  const origin = req.headers.get("origin") || "";
  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
}

interface SendSmsRequest {
  resume_id: string;
  job_id: string;
  to_phone: string;
  message: string;
}

interface TwilioMessageResponse {
  sid: string;
  status: string;
  error_code?: number;
  error_message?: string;
}

/** Send an SMS via Twilio REST API */
async function sendViaTwilio(
  accountSid: string,
  authToken: string,
  fromNumber: string,
  toPhone: string,
  body: string
): Promise<{ ok: boolean; sid?: string; errorMessage?: string }> {
  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;

  const params = new URLSearchParams();
  params.append("To", toPhone);
  params.append("From", fromNumber);
  params.append("Body", body);

  const credentials = btoa(`${accountSid}:${authToken}`);

  const res = await fetch(url, {
    method: "POST",
    headers: {
      "Authorization": `Basic ${credentials}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: params.toString(),
  });

  const json = (await res.json()) as TwilioMessageResponse;

  if (!res.ok) {
    return {
      ok: false,
      errorMessage: json.error_message || `Twilio error (status ${res.status}, code ${json.error_code})`,
    };
  }

  return { ok: true, sid: json.sid };
}

serve(async (req) => {
  const corsHeaders = {
    "Access-Control-Allow-Origin": getCorsOrigin(req),
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  };
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  // Verify JWT
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) {
    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const token = authHeader.replace("Bearer ", "");
  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
  if (authError || !user) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  try {
    const body = (await req.json()) as SendSmsRequest;
    const { resume_id, job_id, to_phone, message } = body;

    if (!resume_id || !job_id || !to_phone || !message) {
      return new Response(
        JSON.stringify({ error: "Missing required fields: resume_id, job_id, to_phone, message" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    if (message.length > 1600) {
      return new Response(
        JSON.stringify({ error: "Message too long. Maximum 1600 characters." }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Load Twilio credentials from Supabase Edge Function Secrets
    const accountSid = Deno.env.get("TWILIO_ACCOUNT_SID");
    const authToken = Deno.env.get("TWILIO_AUTH_TOKEN");
    const fromNumber = Deno.env.get("TWILIO_FROM_NUMBER");

    if (!accountSid || !authToken || !fromNumber) {
      return new Response(
        JSON.stringify({
          error: "SMS not configured. Set TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, and TWILIO_FROM_NUMBER in Supabase Edge Function Secrets.",
          not_configured: true,
        }),
        { status: 503, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Send via Twilio
    const result = await sendViaTwilio(accountSid, authToken, fromNumber, to_phone, message);

    const logStatus = result.ok ? "sent" : "failed";

    // Log to sms_logs regardless of send result
    const { error: logError } = await supabase.from("sms_logs").insert({
      user_id: user.id,
      resume_id,
      job_id,
      to_phone,
      message,
      status: logStatus,
      twilio_sid: result.sid ?? null,
      error: result.errorMessage ?? null,
    });

    if (logError) {
      console.error("Failed to log SMS:", logError.message);
      await logSystemError({
        function_name: "send-sms",
        error_type: "SMS_LOG_ERROR",
        severity: "warning",
        error_message: `Failed to log SMS: ${logError.message}`,
        user_id: user.id,
        job_id,
        resume_id,
      });
    }

    if (!result.ok) {
      console.error("Twilio error:", result.errorMessage);
      await logSystemError({
        function_name: "send-sms",
        error_type: "TWILIO_SEND_ERROR",
        severity: "warning",
        error_message: `Twilio send error: ${result.errorMessage}`,
        user_id: user.id,
        job_id,
        resume_id,
      });
      return new Response(
        JSON.stringify({ error: result.errorMessage }),
        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    return new Response(
      JSON.stringify({ success: true, twilio_sid: result.sid }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (err: unknown) {
    console.error("send-sms error:", err);
    await logSystemError({
      function_name: "send-sms",
      error_type: "SMS_SEND_ERROR",
      severity: "warning",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
      user_id: user.id,
    });
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

interface SendSmsInput {
  resume_id: string;
  job_id: string;
  to_phone: string;
  message: string;
}

interface SendSmsResult {
  success: boolean;
  twilio_sid?: string;
  error?: string;
  not_configured?: boolean;
}

export function useSendSms() {
  const queryClient = useQueryClient();

  return useMutation<SendSmsResult, Error, SendSmsInput>({
    mutationFn: async (input) => {
      const { data, error } = await supabase.functions.invoke<SendSmsResult>("send-sms", {
        body: input,
      });
      if (error) throw new Error(error.message);
      if (!data) throw new Error("No response from send-sms function");
      if (data.error) throw new Error(data.error);
      return data;
    },
    onSuccess: (_data, variables) => {
      // Invalidate sms_logs so any usage history views refresh
      queryClient.invalidateQueries({ queryKey: ["sms_logs"] });
      queryClient.invalidateQueries({ queryKey: ["sms_logs", variables.job_id] });
    },
  });
}

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { MessageSquare, Loader2, Sparkles, AlertTriangle } from "lucide-react";
import { useSendSms } from "@/hooks/useSms";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface SmsOutreachDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  candidateName: string;
  candidatePhone: string;
  jobTitle: string;
  matchScore: number;
  resumeId: string;
  jobId: string;
}

type TemplateKey = "interview_invite" | "application_update" | "custom";

// ─── Templates ───────────────────────────────────────────────────────────────

const TEMPLATES: Record<
  TemplateKey,
  { label: string; build: (name: string, title: string, score: number) => string }
> = {
  interview_invite: {
    label: "Interview Invitation",
    build: (name, title) =>
      `Hi ${name}, this is a message from our recruiting team. We'd love to schedule an interview for the ${title} position. Are you available this week? Please reply with your preferred time.`,
  },
  application_update: {
    label: "Application Update",
    build: (name, title, score) =>
      `Hi ${name}, thanks for applying to the ${title} role. Your profile is a ${score}% match. We're reviewing all candidates and will be in touch within 48 hours.`,
  },
  custom: {
    label: "Custom Message",
    build: (name) => `Hi ${name}, `,
  },
};

// SMS best practice: 160 chars = 1 SMS credit. Over 160 splits into multiple.
const SMS_SOFT_LIMIT = 160;
const SMS_HARD_LIMIT = 1600;

// ─── Character Counter ────────────────────────────────────────────────────────

function CharCounter({ count }: { count: number }) {
  const segments = count === 0 ? 0 : Math.ceil(count / SMS_SOFT_LIMIT);
  const isOver = count > SMS_HARD_LIMIT;
  const isWarning = count > SMS_SOFT_LIMIT && !isOver;

  return (
    <div className="flex items-center justify-between">
      <p className="text-[11px] text-muted-foreground">
        {count > SMS_SOFT_LIMIT && (
          <span className={isOver ? "text-destructive" : "text-amber-600"}>
            {segments} SMS segment{segments !== 1 ? "s" : ""}
            {" "}
          </span>
        )}
        Keep under 160 characters for a single SMS segment.
      </p>
      <span
        className={`text-[11px] tabular-nums font-mono ${
          isOver
            ? "text-destructive"
            : isWarning
            ? "text-amber-600"
            : "text-muted-foreground"
        }`}
      >
        {count}/{SMS_SOFT_LIMIT}
      </span>
    </div>
  );
}

// ─── Dialog ───────────────────────────────────────────────────────────────────

const SmsOutreachDialog = ({
  open,
  onOpenChange,
  candidateName,
  candidatePhone,
  jobTitle,
  matchScore,
  resumeId,
  jobId,
}: SmsOutreachDialogProps) => {
  const [template, setTemplate] = useState<TemplateKey>("interview_invite");
  const [message, setMessage] = useState("");
  const sendSms = useSendSms();

  // Reset when dialog opens
  useEffect(() => {
    if (open) {
      setTemplate("interview_invite");
      setMessage(
        TEMPLATES.interview_invite.build(candidateName, jobTitle, matchScore)
      );
    }
  }, [open, candidateName, jobTitle, matchScore]);

  const handleTemplateChange = (key: TemplateKey) => {
    setTemplate(key);
    setMessage(TEMPLATES[key].build(candidateName, jobTitle, matchScore));
  };

  const hasPhone = candidatePhone.trim().length > 0;

  const handleSend = async () => {
    if (!message.trim()) {
      toast.error("Please enter a message");
      return;
    }
    if (!hasPhone) {
      toast.error("No phone number on file for this candidate");
      return;
    }
    if (message.length > SMS_HARD_LIMIT) {
      toast.error(`Message too long (max ${SMS_HARD_LIMIT} characters)`);
      return;
    }

    try {
      await sendSms.mutateAsync({
        resume_id: resumeId,
        job_id: jobId,
        to_phone: candidatePhone,
        message: message.trim(),
      });
      toast.success(`SMS sent to ${candidateName}`);
      onOpenChange(false);
    } catch (err: unknown) {
      const errMsg = err instanceof Error ? err.message : String(err);
      if (errMsg.includes("not configured") || errMsg.includes("SMS not configured")) {
        toast.error("SMS not configured. Ask your admin to add Twilio credentials.");
      } else {
        toast.error(`Failed to send SMS: ${errMsg}`);
      }
    }
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(message);
    toast.success("Message copied to clipboard");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[540px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <MessageSquare className="h-4 w-4 text-primary" />
            SMS {candidateName}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Phone — read-only */}
          <div className="space-y-1.5">
            <Label htmlFor="sms-phone">Phone Number</Label>
            {hasPhone ? (
              <Input
                id="sms-phone"
                value={candidatePhone}
                readOnly
                className="bg-muted text-muted-foreground cursor-not-allowed font-mono text-sm"
              />
            ) : (
              <div className="flex items-center gap-2 rounded-md border border-destructive/40 bg-destructive/5 px-3 py-2 text-sm text-destructive">
                <AlertTriangle className="h-4 w-4 shrink-0" />
                No phone number on file for this candidate
              </div>
            )}
          </div>

          {/* Template selector */}
          <div className="space-y-1.5">
            <Label>Message Template</Label>
            <div className="flex items-center gap-2">
              <Select
                value={template}
                onValueChange={(v) => handleTemplateChange(v as TemplateKey)}
              >
                <SelectTrigger className="h-9">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {Object.entries(TEMPLATES).map(([key, { label }]) => (
                    <SelectItem key={key} value={key}>
                      {label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <div className="flex items-center gap-1 text-xs text-muted-foreground shrink-0">
                <Sparkles className="h-3 w-3 text-primary" />
                Pre-built
              </div>
            </div>
          </div>

          {/* Message — editable */}
          <div className="space-y-1.5">
            <div className="flex items-center justify-between">
              <Label htmlFor="sms-message">Message</Label>
              {message.length <= SMS_SOFT_LIMIT && (
                <Badge variant="outline" className="text-[11px]">
                  1 SMS
                </Badge>
              )}
            </div>
            <Textarea
              id="sms-message"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              rows={6}
              placeholder="Type your message..."
              className="resize-none text-sm"
              maxLength={SMS_HARD_LIMIT}
            />
            <CharCounter count={message.length} />
          </div>

          {/* Delivery note */}
          <p className="text-[11px] text-muted-foreground bg-muted/50 rounded-md px-3 py-2">
            Sent via Twilio. The candidate will receive a real text message. Message and delivery status are logged.
          </p>
        </div>

        <DialogFooter className="flex-col-reverse sm:flex-row gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handleCopy}
            className="gap-1.5"
            disabled={sendSms.isPending}
          >
            Copy Message
          </Button>
          <Button
            onClick={handleSend}
            className="gap-1.5"
            disabled={sendSms.isPending || !hasPhone || message.length > SMS_HARD_LIMIT}
          >
            {sendSms.isPending ? (
              <>
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
                Sending...
              </>
            ) : (
              <>
                <MessageSquare className="h-3.5 w-3.5" />
                Send SMS
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default SmsOutreachDialog;

