            </div>
          </div>

          {/* Setup guide */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Setup Guide</p>
            <div className="space-y-3 rounded-lg bg-muted/40 p-4">
              <Step n={1} text={<>Sign up at <a href="https://www.twilio.com/try-twilio" target="_blank" rel="noopener noreferrer" className="text-primary underline font-medium">twilio.com</a> — free trial includes test credits</>} />
              <Step n={2} text={<>Go to <strong>Console Dashboard</strong> — copy your <strong>Account SID</strong> and <strong>Auth Token</strong></>} />
              <Step n={3} text={<>Go to <strong>Phone Numbers → Buy a Number</strong>, purchase a number with SMS capability. Copy in E.164 format (e.g. <code className="bg-background px-1 rounded text-xs">+15551234567</code>)</>} />
              <Step n={4} text={<>In Supabase dashboard → <strong>Project Settings → Edge Functions → Secrets</strong>, add all three secrets:<br />
                <span className="block mt-1 space-y-0.5 ml-1">
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">TWILIO_ACCOUNT_SID</code></span>
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">TWILIO_AUTH_TOKEN</code></span>
                  <span className="block text-xs">• <code className="bg-background px-1 rounded">TWILIO_FROM_NUMBER</code></span>
                </span>
              </>} />
              <Step n={5} text={<>Deploy the edge function: <code className="bg-background px-1 rounded text-xs">supabase functions deploy send-sms</code></>} />
              <Step n={6} text="Send a test SMS below to verify everything is working" />
            </div>
          </div>

          {/* Test send */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-3">Send Test SMS</p>
            <div className="rounded-lg border p-4 space-y-3">
              <div>
                <Label className="text-xs font-medium">Phone Number</Label>
                <p className="text-xs text-muted-foreground mb-1.5">Enter a real number to receive the test — must be in E.164 format</p>
                <div className="flex gap-2">
                  <Input
                    value={testPhone}
                    onChange={(e) => setTestPhone(e.target.value)}
                    placeholder="+15551234567"
                    className="font-mono text-sm flex-1"
                  />
                  <Button
                    size="sm"
                    onClick={handleTestSms}
                    disabled={sendingTest || !testPhone}
                    variant="outline"
                  >
                    {sendingTest
                      ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      : <MessageSquare className="h-3.5 w-3.5" />}
                    <span className="ml-1.5">Send Test</span>
                  </Button>
                </div>
              </div>
            </div>
          </div>

          {/* Used by */}
          <div>
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground mb-2">Used By</p>
            <div className="flex flex-wrap gap-1.5">
              {["send-sms"].map(fn => (
                <Badge key={fn} variant="outline" className="text-xs font-mono">{fn}</Badge>
              ))}
            </div>
            <p className="text-xs text-muted-foreground mt-2">
              Used by the SMS Outreach dialog on candidate cards to send interview invitations and application updates.
            </p>
          </div>

          <Separator />

          <div className="flex items-center justify-between">
            <p className="text-xs text-muted-foreground">
              {integration?.last_tested_at
                ? <>Last tested: {new Date(integration.last_tested_at).toLocaleString()}</>
                : "Never tested"}
            </p>
            <Button variant="ghost" size="sm" asChild>
              <a href="https://console.twilio.com" target="_blank" rel="noopener noreferrer">
                <ExternalLink className="h-3.5 w-3.5 mr-1.5" />Console
              </a>
            </Button>
          </div>
        </div>
      </CollapsibleContent>
    </Collapsible>
  );
};

